{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C17","C23","C05","C15","C04","C19","C22","C06","C07","C01","C18","C10","C21","C03","C08","C11","C26","C31","C37","C39","C40","C41","C43","C44"],
  "contradictory_card_ids": ["C42"],
  "prediction_basis_card_ids": ["C17","C23","C05","C15","C04","C19","C22","C06","C07","C01","C18","C10","C21","C03","C08","C11","C26"],
  "claims": [
    {
      "claim": "In fasted humans, SRT2104, a thiazole-containing high-molecular-weight oral drug, had absolute oral bioavailability of 13.8% (range 2-27%) after a 0.25 g oral suspension with an IV microdose reference, below the 20% threshold.",
      "card_ids": ["C17","C23","C37"]
    },
    {
      "claim": "Multiple reference peptidomimetic and lipophilic oral drugs have human absolute oral F below 20%: revefenacin <3%, lopinavir poor or very low, alvimopan 6%, octreotide 0.3-0.6%, GHRP-6 about 0.3%, renin inhibitors <2%, and cromolyn about 1%.",
      "card_ids": ["C05","C15","C04","C19","C22","C06","C07","C01","C18","C10","C21","C03","C08","C11","C26"]
    },
    {
      "claim": "L2 context records reinforce the low-F pattern in additional species and formulations: GHRP-6 about 1% in rat, cromolyn 0.1% in rat, renin inhibitors <1-2%, alvimopan poor in canine, and lopinavir proliposome only a relative increase over pure drug.",
      "card_ids": ["C31","C39","C40","C34","C44","C36","C38"]
    },
    {
      "claim": "The only L2 value above 20% is lopinavir 25% in male Wistar rats, which conflicts with multiple human L1 records showing poor or very low lopinavir bioavailability and is a non-voting rat context record; it does not overturn the human low-F evidence.",
      "card_ids": ["C42","C04","C09","C19","C22"]
    },
    {
      "claim": "Mouse octreotide relative bioavailability values versus subcutaneous dosing with Intravail permeation enhancer are not absolute oral F values and are not threshold-relevant for the F >= 20% decision.",
      "card_ids": ["C32","C33"]
    },
    {
      "claim": "No visible record provides affirmative threshold-relevant evidence for query F >= 20%; all transferable human absolute-oral-F outcomes are below threshold.",
      "card_ids": ["C17","C23","C05","C15","C04","C19","C22","C06","C07","C01","C18","C10","C21","C03","C08","C11","C26"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C31","C32","C33","C34","C35","C36","C37","C38","C39","C40","C41","C42","C43","C44"]
    }
  ],
  "evidence_gaps": [
    "Direct oral bioavailability of the query molecule itself has not been measured in any visible record; all F values come from reference contexts.",
    "Fasted-state data are explicit only for SRT2104; other low-F contexts lack prandial detail, so fasted transfer is inferred.",
    "First-pass metabolism, solubility, and formulation effects for the query are not directly characterized; the low prediction relies on analog transfer and physicochemical priors.",
    "The rat lopinavir 25% value and mouse octreotide relative values are species and formulation specific and cannot be mapped to the human absolute F threshold."
  ],
  "decision_summary": "Prediction remains low and is strengthened. All transferable human absolute-oral-F reference records are below 20%, including fasted SRT2104 at 13.8% and multiple structurally analogous peptidomimetics with low F. L2 context records largely reinforce this pattern across rat, mouse, and canine models. The single above-threshold value, rat lopinavir 25%, is species-specific, non-voting, and contradicted by human L1 records showing poor lopinavir bioavailability. The query's high molecular weight, high logP and logD, high TPSA, neutral charge, and many rotatable bonds are consistent with the low-F pattern. No affirmative evidence supports F >= 20%."
}

